const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

/**
 * Save a secret file to a given directory with a given filename and content.
 * The file should be accessible only by the current user.
 *
 * @param {string} directory - The directory to save the secret file.
 * @param {string} filename - The filename of the secret file.
 * @param {string} content - The content of the secret file.
 */
function saveSecretFile(directory, filename, content) {
  // Ensure the target directory exists. If it doesn't, create it recursively.
  fs.mkdirSync(directory, { recursive: true });

  const finalFilePath = path.join(directory, filename);
  // Generate a unique temporary filename to prevent conflicts and enhance security.
  const tempFilename = `${filename}.${crypto.randomBytes(8).toString('hex')}.tmp`;
  const tempFilePath = path.join(directory, tempFilename);

  let fd; // File descriptor for the temporary file
  try {
    // 1. Create a temporary file exclusively with restrictive permissions (0o600).
    // The 'wx' flag ensures:
    //   - 'w': The file is opened for writing.
    //   - 'x': The operation fails if the path exists. This is crucial for security
    //          as it prevents overwriting existing files (including symbolic links)
    //          and ensures we are creating a new, controlled file.
    // The 'mode' 0o600 sets read/write permissions for the owner only,
    // preventing access by group or others from the moment of creation.
    fd = fs.openSync(tempFilePath, 'wx', 0o600);

    // 2. Write the content to the securely created temporary file.
    fs.writeSync(fd, content);

    // 3. Close the temporary file descriptor.
    fs.closeSync(fd);
    fd = null; // Mark as closed to prevent double-closing in finally block

    // 4. Atomically rename the temporary file to the final filename.
    // This operation is atomic on most file systems. It replaces the target file
    // (if it exists) with the new temporary file. This is a robust way to update
    // files securely, as it avoids race conditions and symlink attacks that
    // could occur if we were to write directly to the final path.
    // The permissions of the temporary file (0o600) are preserved during the rename.
    fs.renameSync(tempFilePath, finalFilePath);

    // 5. Explicitly set permissions on the final file one last time.
    // While rename preserves permissions from the source (temp file), this step
    // provides an additional layer of defense to guarantee the 0o600 permissions
    // for the final file, addressing any potential edge cases or filesystem quirks.
    // This ensures the file is accessible only by the current user.
    fs.chmodSync(finalFilePath, 0o600);

  } finally {
    // Ensure the file descriptor is closed if it was opened but not yet closed
    // (e.g., if an error occurred during write).
    if (fd) {
      try {
        fs.closeSync(fd);
      } catch (e) {
        // Ignore errors during close in a finally block, as the primary error
        // (if any) would have already been thrown.
      }
    }
    // Clean up the temporary file if it still exists (e.g., if rename failed).
    if (fs.existsSync(tempFilePath)) {
      try {
        fs.unlinkSync(tempFilePath);
      } catch (e) {
        // Ignore errors during unlink in a finally block.
      }
    }
  }
}
